const i = $.input;
const params = {};

if (i.email) params.email = i.email;
if (i.firstName) params.first_name = i.firstName;
if (i.lastName) params.last_name = i.lastName;
if (i.domain) params.domain = i.domain;
if (i.linkedinUrl) params.linkedin_url = i.linkedinUrl;
if (i.apolloPersonId) params.id = i.apolloPersonId;
if (i.revealPersonalEmails) params.reveal_personal_emails = 'true';

// Validate at least one identifier is provided
const hasId = i.email || i.linkedinUrl || i.apolloPersonId || (i.firstName && i.domain) || (i.firstName && i.lastName);
if (!hasId) throw new Error('Provide at least one identifier: email, linkedinUrl, apolloPersonId, or firstName+domain/lastName');

return { params };

const resp = $.steps.enrichPerson.response || {};
const p = resp.person;

if (!p) return { found: false, summary: 'No match found. Try providing more identifiers (email, domain, LinkedIn URL).' };

const org = p.organization || {};
const employment = (p.employment_history || []).map(e => ({
  title: e.title,
  company: e.organization_name,
  current: e.current || false,
  startDate: e.start_date,
  endDate: e.end_date
}));

return {
  found: true,
  person: {
    id: p.id,
    name: p.name,
    firstName: p.first_name,
    lastName: p.last_name,
    title: p.title,
    headline: p.headline,
    email: p.email || null,
    emailStatus: p.email_status || null,
    linkedinUrl: p.linkedin_url || null,
    city: p.city,
    state: p.state,
    country: p.country,
    seniority: p.seniority,
    departments: p.departments || [],
    isLikelyToEngage: p.is_likely_to_engage || false
  },
  organization: {
    id: org.id,
    name: org.name,
    domain: org.primary_domain,
    industry: org.industry,
    employees: org.estimated_num_employees,
    revenue: org.annual_revenue_printed,
    linkedinUrl: org.linkedin_url
  },
  employment,
  summary: `Enriched: ${p.name} - ${p.title || 'Unknown title'} at ${org.name || 'Unknown company'}`
};
